// Package spec is snif's box-id grammar and widget model — the contract that
// makes a snorg template a snif form.
//
// snif stores no configuration of its own. Everything it needs about a widget is
// encoded in the id of a snorg template box (docs/widgets.md), so a `templates:`
// section generated by snif is the complete, self-describing contract: readable by
// `snorg query region[<id>]`, by snif, and by a human looking at the YAML. This
// package is the single place that grammar lives — Parse turns an id into an ID,
// Build assembles a page's boxes into Widgets, and Widget.Boxes is the exact
// inverse, so the generator can never emit an id the reader cannot read.
//
// It deliberately depends on nothing: neither snorg nor YAML, so the grammar is
// testable on its own and the layout/draw packages that share it stay free of the
// archive.
package spec

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

// Kind is a widget's type, and the first segment of every one of its box ids.
type Kind string

const (
	// Check is a single box holding a tick: ink present or absent.
	Check Kind = "check"
	// Button is a Check that means "act on this page" rather than "this is true".
	// Same ink rule, different intent — a consumer can react to one and store the
	// other.
	Button Kind = "button"
	// Input is a free-text writing area — the only kind whose value is text, and
	// therefore the only box snif marks analyze: true for snorg's vision model.
	Input Kind = "input"
	// Slider is a track whose value is the position of the rightmost ink.
	Slider Kind = "slider"
	// Radio is a group of cells of which exactly one may be ticked.
	Radio Kind = "radio"
	// Date is three Radio-like groups (day, month, year) read as one date.
	Date Kind = "date"
)

// kinds is the parse table: every known first segment.
var kinds = map[Kind]bool{Check: true, Button: true, Input: true, Slider: true, Radio: true, Date: true}

// Part names a date group's sub-group. It is the third segment of a date cell id
// (date:<name>:<part>:<key>), which is also what tells a date cell apart from a
// date widget id (date:<name>:<year0>:<year1>, whose third segment is a number).
type Part string

const (
	Day   Part = "day"
	Month Part = "month"
	Year  Part = "year"
)

// parts lists the date sub-groups in the order they are laid out and read.
var parts = []Part{Day, Month, Year}

func isPart(s string) bool { return Part(s) == Day || Part(s) == Month || Part(s) == Year }

// ident is the charset of a widget name and of a radio cell key: an alphanumeric
// start then alphanumerics, underscore, dash or dot. It excludes ':' (the segment
// separator) and whitespace, and stays inside snorg's query [scope] token so
// `snorg query 'region[input:notes]:x'` parses.
var ident = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9_.-]*$`)

// ErrNotWidget marks an id that is not snif's at all — an ordinary snorg template
// box. Callers reading a page ignore these; they are not errors of authorship.
var ErrNotWidget = fmt.Errorf("not a snif widget id")

// ID is one parsed box id. It is sparse: which fields carry meaning depends on
// Kind and on whether the id names a widget or one of its cells (Cell != "").
//
//	check:done              Kind=check  Name=done
//	button:submit           Kind=button Name=submit
//	input:notes             Kind=input  Name=notes
//	slider:mood:0:10:0.5    Kind=slider Name=mood  Min=0 Max=10 Step=0.5
//	radio:prio              Kind=radio  Name=prio                        (the group)
//	radio:prio:low          Kind=radio  Name=prio  Cell=low              (one option)
//	date:due:2026:2030      Kind=date   Name=due   Year0=2026 Year1=2030 (the group)
//	date:due:month:09       Kind=date   Name=due   Part=month Cell=09    (one option)
type ID struct {
	Kind Kind
	Name string

	Cell string // the cell key; "" on a widget-level id
	Part Part   // a date cell's sub-group; "" otherwise

	Min, Max, Step float64 // slider bounds and snap (Step 0 = no snapping)
	Year0, Year1   int     // date year range, inclusive
}

// IsCell reports whether the id names one cell of a group rather than the widget.
func (id ID) IsCell() bool { return id.Cell != "" }

// Parse reads a box id. It returns ErrNotWidget (wrapped) when the id does not
// begin with a known kind — that is an ordinary snorg box, not a mistake — and a
// descriptive error when the kind is known but the rest is malformed, which is an
// authoring bug worth reporting.
func Parse(s string) (ID, error) {
	seg := strings.Split(s, ":")
	kind := Kind(seg[0])
	if !kinds[kind] {
		return ID{}, fmt.Errorf("%q: %w", s, ErrNotWidget)
	}
	if len(seg) < 2 || !ident.MatchString(seg[1]) {
		return ID{}, fmt.Errorf("%q: %s needs a name (%s:<name>…)", s, kind, kind)
	}
	id := ID{Kind: kind, Name: seg[1]}
	args := seg[2:]

	switch kind {
	case Check, Button, Input:
		if len(args) != 0 {
			return ID{}, fmt.Errorf("%q: %s takes no arguments (%s:<name>)", s, kind, kind)
		}
	case Slider:
		if len(args) < 2 || len(args) > 3 {
			return ID{}, fmt.Errorf("%q: slider needs bounds (slider:<name>:<min>:<max>[:<step>])", s)
		}
		var err error
		if id.Min, err = num(args[0]); err != nil {
			return ID{}, fmt.Errorf("%q: slider min: %w", s, err)
		}
		if id.Max, err = num(args[1]); err != nil {
			return ID{}, fmt.Errorf("%q: slider max: %w", s, err)
		}
		if id.Max <= id.Min {
			return ID{}, fmt.Errorf("%q: slider max must exceed min", s)
		}
		if len(args) == 3 {
			if id.Step, err = num(args[2]); err != nil {
				return ID{}, fmt.Errorf("%q: slider step: %w", s, err)
			}
			if id.Step <= 0 {
				return ID{}, fmt.Errorf("%q: slider step must be positive", s)
			}
		}
	case Radio:
		switch len(args) {
		case 0: // the group
		case 1:
			if !ident.MatchString(args[0]) {
				return ID{}, fmt.Errorf("%q: bad radio option key %q", s, args[0])
			}
			id.Cell = args[0]
		default:
			return ID{}, fmt.Errorf("%q: radio is radio:<name> or radio:<name>:<option>", s)
		}
	case Date:
		if len(args) != 2 {
			return ID{}, fmt.Errorf("%q: date is date:<name>:<year0>:<year1> or date:<name>:<day|month|year>:<key>", s)
		}
		if isPart(args[0]) {
			id.Part, id.Cell = Part(args[0]), args[1]
			if _, err := id.CellNumber(); err != nil {
				return ID{}, fmt.Errorf("%q: %w", s, err)
			}
			break
		}
		var err error
		if id.Year0, err = year(args[0]); err != nil {
			return ID{}, fmt.Errorf("%q: date year0: %w", s, err)
		}
		if id.Year1, err = year(args[1]); err != nil {
			return ID{}, fmt.Errorf("%q: date year1: %w", s, err)
		}
		if id.Year1 < id.Year0 {
			return ID{}, fmt.Errorf("%q: date year range runs backwards", s)
		}
	}
	return id, nil
}

// String formats the id back into its canonical text — the exact inverse of
// Parse, so an id survives a Parse/String round-trip byte for byte.
func (id ID) String() string {
	b := []string{string(id.Kind), id.Name}
	switch {
	case id.Kind == Slider:
		b = append(b, fnum(id.Min), fnum(id.Max))
		if id.Step > 0 {
			b = append(b, fnum(id.Step))
		}
	case id.Kind == Radio && id.IsCell():
		b = append(b, id.Cell)
	case id.Kind == Date && id.IsCell():
		b = append(b, string(id.Part), id.Cell)
	case id.Kind == Date:
		b = append(b, strconv.Itoa(id.Year0), strconv.Itoa(id.Year1))
	}
	return strings.Join(b, ":")
}

// CellNumber is a date cell's key as an integer, range-checked against its
// sub-group: 1..31 for a day, 1..12 for a month, a four-digit year.
func (id ID) CellNumber() (int, error) {
	n, err := strconv.Atoi(id.Cell)
	if err != nil {
		return 0, fmt.Errorf("date %s cell %q is not a number", id.Part, id.Cell)
	}
	switch id.Part {
	case Day:
		if n < 1 || n > 31 {
			return 0, fmt.Errorf("date day %d out of range 1..31", n)
		}
	case Month:
		if n < 1 || n > 12 {
			return 0, fmt.Errorf("date month %d out of range 1..12", n)
		}
	case Year:
		if n < 1000 || n > 9999 {
			return 0, fmt.Errorf("date year %d is not four digits", n)
		}
	}
	return n, nil
}

// num parses a slider bound, rejecting the forms strconv accepts but a template
// should never carry (Inf/NaN).
func num(s string) (float64, error) {
	v, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0, fmt.Errorf("%q is not a number", s)
	}
	if v != v || v > 1e15 || v < -1e15 {
		return 0, fmt.Errorf("%q is out of range", s)
	}
	return v, nil
}

// fnum formats a slider bound in the shortest form that parses back exactly, so
// String is a true inverse of Parse.
func fnum(v float64) string { return strconv.FormatFloat(v, 'g', -1, 64) }

func year(s string) (int, error) {
	n, err := strconv.Atoi(s)
	if err != nil || n < 1000 || n > 9999 {
		return 0, fmt.Errorf("%q is not a four-digit year", s)
	}
	return n, nil
}

// CellKey formats a date cell key canonically: days and months zero-padded to two
// digits so ids sort in calendar order, years as they are.
func CellKey(p Part, n int) string {
	if p == Year {
		return strconv.Itoa(n)
	}
	return fmt.Sprintf("%02d", n)
}
